class Launcher { public static bool SelfTest=false; public static string PreviewFile,ReviewReport;public static bool PreviewOnly;
 [STAThread] static void Main(string[] args) {
  Application.EnableVisualStyles(); Application.SetCompatibleTextRenderingDefault(false);
  int reviewArg=Array.IndexOf(args,"--review-report");if(reviewArg>=0&&reviewArg+1<args.Length)ReviewReport=args[reviewArg+1];PreviewOnly=args.Contains("--preview-only");int fileArg=Array.IndexOf(args,"--preview-file");if(fileArg>=0&&fileArg+1<args.Length)PreviewFile=args[fileArg+1];
  try { if(args.Contains("--self-test")) { SelfTest=true; using(var f=new DoctorForm()){f.ShowInTaskbar=false;f.Opacity=0;f.Shown+=async(sender,e)=>{try{await f.CheckLayout();File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"build","gui-smoke.txt"),"PASS: native Windows interface, RU/EN, engine job, report protocol and preview.");}catch(Exception error){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"build","gui-error.txt"),error.ToString());Environment.ExitCode=1;}finally{f.Close();}};Application.Run(f);} return;} Application.Run(new DoctorForm()); }
  catch(Exception e){if(args.Contains("--self-test")){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"build","gui-error.txt"),e.ToString());Environment.Exit(1);}MessageBox.Show(e.ToString(),"CNC File Doctor");}
 }
}
struct WorldPoint {public double X,Y;public WorldPoint(double x,double y){X=x;Y=y;}}
class PreviewMarker {public WorldPoint Point;public string Message;}
class DrawingPanel : Panel {
 public List<WorldPoint[]> Curves=new List<WorldPoint[]>();public List<Color> Colors=new List<Color>();public Dictionary<int,Color> RoleColors=new Dictionary<int,Color>();public bool ShowContourRoles=true;
 public HashSet<int> Changed=new HashSet<int>(),Pending=new HashSet<int>();public List<PreviewMarker> Problems=new List<PreviewMarker>();
 public string Message="Добавьте DXF для просмотра / Add a DXF to preview",Units="mm";public bool ShowMarkers=true,Russian=true;
 double zoom=1,panX,panY,cx,cy,baseScale=1;int targetIndex;bool dragging;Point last;ToolTip tip=new ToolTip();string lastTip;
 public DrawingPanel(){DoubleBuffered=true;BackColor=Color.FromArgb(13,22,36);TabStop=true;Cursor=Cursors.Cross;}
 public void Fit(){zoom=1;panX=panY=0;targetIndex=0;Invalidate();}
 public void NextTarget(){var targets=Problems.Select(p=>p.Point).Concat(Changed.Concat(Pending).Distinct().Where(i=>i<Curves.Count&&Curves[i].Length>0).Select(i=>Curves[i][Curves[i].Length/2])).ToArray();if(targets.Length==0)return;var target=targets[targetIndex++%targets.Length];zoom=50;panX=-(target.X-cx)*baseScale*zoom;panY=(target.Y-cy)*baseScale*zoom;Invalidate();}
 public void Zoom(double factor,Point anchor){double next=Math.Max(.1,Math.Min(100000,zoom*factor)),ratio=next/zoom;panX=anchor.X-Width/2-(anchor.X-Width/2-panX)*ratio;panY=anchor.Y-Height/2-(anchor.Y-Height/2-panY)*ratio;zoom=next;Invalidate();}
 protected override void OnMouseEnter(EventArgs e){base.OnMouseEnter(e);Focus();}
 protected override void OnMouseWheel(MouseEventArgs e){base.OnMouseWheel(e);Zoom(e.Delta>0?1.25:.8,e.Location);}
 protected override void OnMouseDoubleClick(MouseEventArgs e){base.OnMouseDoubleClick(e);Fit();}
 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button==MouseButtons.Left||e.Button==MouseButtons.Middle){dragging=true;last=e.Location;Capture=true;Cursor=Cursors.Hand;}}
 protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);dragging=false;Capture=false;Cursor=Cursors.Cross;}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(dragging){panX+=e.X-last.X;panY+=e.Y-last.Y;last=e.Location;Invalidate();return;}string text=null;foreach(var p in Problems){var q=Screen(p.Point);if(Math.Abs(q.X-e.X)<12&&Math.Abs(q.Y-e.Y)<12){text=p.Message;break;}}if(text!=lastTip){lastTip=text;tip.SetToolTip(this,text);}}
 protected override void OnResize(EventArgs e){base.OnResize(e);Invalidate();}
 PointF Screen(WorldPoint p){return new PointF((float)(Width/2+panX+(p.X-cx)*baseScale*zoom),(float)(Height/2+panY-(p.Y-cy)*baseScale*zoom));}
 static double Nice(double x){double p=Math.Pow(10,Math.Floor(Math.Log10(Math.Max(x,1e-20))));double r=x/p;return (r<=1?1:r<=2?2:r<=5?5:10)*p;}
 protected override void OnPaint(PaintEventArgs e){
  base.OnPaint(e);var all=Curves.SelectMany(x=>x).ToArray();
  if(all.Length==0){TextRenderer.DrawText(e.Graphics,Message,Font,new Rectangle(25,25,Math.Max(1,Width-50),Math.Max(1,Height-50)),Color.LightSteelBlue,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.WordBreak);return;}
  double xmin=all.Min(p=>p.X),xmax=all.Max(p=>p.X),ymin=all.Min(p=>p.Y),ymax=all.Max(p=>p.Y);cx=(xmin+xmax)/2;cy=(ymin+ymax)/2;
  baseScale=Math.Max(1e-15,Math.Min(Math.Max(1,Width-90)/Math.Max(xmax-xmin,1e-9),Math.Max(1,Height-100)/Math.Max(ymax-ymin,1e-9)));double scale=baseScale*zoom,step=Nice(85/scale);
  using(var grid=new Pen(Color.FromArgb(28,43,62))){double xleft=cx+(-Width/2-panX)/scale,ybottom=cy+(panY-Height/2)/scale;for(int i=0;i<200;i++){double x=(Math.Ceiling(xleft/step)+i)*step;var point=Screen(new WorldPoint(x,cy));if(point.X>Width)break;e.Graphics.DrawLine(grid,point.X,0,point.X,Height);}for(int i=0;i<200;i++){double y=(Math.Ceiling(ybottom/step)+i)*step;var point=Screen(new WorldPoint(cx,y));if(point.Y<0)break;e.Graphics.DrawLine(grid,0,point.Y,Width,point.Y);}}
  e.Graphics.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;e.Graphics.PixelOffsetMode=System.Drawing.Drawing2D.PixelOffsetMode.HighQuality;
  for(int i=0;i<Curves.Count;i++){
   Color color=i<Colors.Count?Colors[i]:Color.FromArgb(110,217,247);if(ShowMarkers&&Changed.Contains(i))color=Color.FromArgb(83,232,160);else if(ShowMarkers&&Pending.Contains(i))color=Color.FromArgb(255,196,80);
   if(color.GetBrightness()<.18)color=Color.FromArgb(140,151,168);
   if(ShowContourRoles&&RoleColors.ContainsKey(i))color=RoleColors[i];using(var pen=new Pen(color,Changed.Contains(i)?2.3f:1.7f)){pen.StartCap=pen.EndCap=System.Drawing.Drawing2D.LineCap.Round;var points=Curves[i].Select(Screen).ToArray();if(points.Length>=2)e.Graphics.DrawLines(pen,points);}
  }
  if(ShowMarkers){using(var halo=new SolidBrush(Color.FromArgb(170,25,20,28)))using(var pen=new Pen(Color.FromArgb(255,93,105),2.5f)){foreach(var marker in Problems){var q=Screen(marker.Point);var diamond=new[]{new PointF(q.X,q.Y-10),new PointF(q.X+10,q.Y),new PointF(q.X,q.Y+10),new PointF(q.X-10,q.Y)};e.Graphics.FillPolygon(halo,diamond);e.Graphics.DrawPolygon(pen,diamond);using(var warningFont=new Font(Font.FontFamily,10,FontStyle.Bold))e.Graphics.DrawString("!",warningFont,Brushes.White,q.X-4,q.Y-8);}}}
  using(var brush=new SolidBrush(Color.FromArgb(184,200,218)))using(var small=new Font(Font.FontFamily,8)){string title=(xmax-xmin).ToString("0.###")+" × "+(ymax-ymin).ToString("0.###")+" "+Units+"    "+(zoom*100).ToString("0")+"%";e.Graphics.DrawString(title,Font,brush,12,10);e.Graphics.DrawString((Russian?"Сетка: ":"Grid: ")+step.ToString("0.########")+" "+Units,Font,brush,12,Height-45);e.Graphics.DrawString(ShowContourRoles&&RoleColors.Count>0?(Russian?"Контуры: голубой — наружный; жёлтый — отверстие; фиолетовый — островок; красный ! — проблема":"Contours: cyan — outer; amber — hole; violet — island; red ! — issue"):(Russian?"Маркеры: красный ! — проблема; жёлтый — сплайны/полилинии; зелёный — изменённые":"Markers: red ! — issue; amber — splines/polylines; green — changed"),small,brush,12,Height-24);}
 }
 protected override void Dispose(bool disposing){if(disposing)tip.Dispose();base.Dispose(disposing);}
}
