 void Add(IEnumerable<string> paths){if(busy)return;foreach(var p in paths){string f=Path.GetFullPath(p);if(!files.Contains(f,StringComparer.OrdinalIgnoreCase)){files.Add(f);table.Items.Add(new ListViewItem(new[]{Path.GetFileName(f),"—",""}){ToolTipText=f});}}EnsureSelection();UpdateDashboard(CurrentFile());}
 void EnsureSelection(){if(table.SelectedIndices.Count==0&&table.Items.Count>0){table.Items[0].Selected=true;table.Items[0].Focused=true;table.Items[0].EnsureVisible();}}
 void AddFiles(){using(var d=new OpenFileDialog(){Filter="DXF files|*.dxf",Multiselect=true})if(d.ShowDialog()==DialogResult.OK)Add(d.FileNames);}
 async Task AddFolder(){using(var d=new FolderBrowserDialog())if(d.ShowDialog()==DialogResult.OK){try{string path=d.SelectedPath;var found=await Task.Run(()=>Python("--discover "+Quote(path)));if(found.Item1!=0)throw new Exception(found.Item3);Add(((System.Collections.IList)json.DeserializeObject(found.Item2)).Cast<object>().Select(x=>x.ToString()));}catch(Exception e){MessageBox.Show(e.Message);}}}
 string ResultFolder(){if(table.SelectedIndices.Count>0){var tag=table.SelectedItems[0].Tag as string;if(tag!=null){var item=json.Deserialize<Dictionary<string,object>>(tag);if(item.ContainsKey("processedFolder"))return (string)item["processedFolder"];}}return null;}
 void UpdateLocation(){string folder=ResultFolder();output.Text=folder??(lang.SelectedIndex==0?"Автоматически: исходная папка\\имя_папки_N":"Automatic: source folder\\folder_name_N");buttons[6].Enabled=!busy&&folder!=null&&Directory.Exists(folder);browse.Enabled=buttons[6].Enabled;}
