 void OpenReport(){string path=report;if(table.SelectedIndices.Count>0&&table.SelectedItems[0].Tag!=null){var item=json.Deserialize<Dictionary<string,object>>((string)table.SelectedItems[0].Tag);if(item.ContainsKey("reportPath"))path=(string)item["reportPath"];}if(path!=null&&File.Exists(path))Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}
