 string Quote(string s){return "\""+s.Replace("\"","\\\"")+"\"";}
 Tuple<int,string,string> Python(string args){using(var p=new Process(){StartInfo=new ProcessStartInfo(Path.Combine(root,"runtime","python.exe"),"-I "+Quote(Path.Combine(root,"src","doctor.py"))+" "+args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8,WorkingDirectory=root}}){var a=new StringBuilder();var b=new StringBuilder();p.OutputDataReceived+=(sender,e)=>{if(e.Data!=null)lock(a)a.AppendLine(e.Data);};p.ErrorDataReceived+=(sender,e)=>{if(e.Data!=null)lock(b)b.AppendLine(e.Data);};p.Start();p.BeginOutputReadLine();p.BeginErrorReadLine();p.WaitForExit();return Tuple.Create(p.ExitCode,a.ToString(),b.ToString());}}
 async Task Run(bool convert,string[] splitCriteria=null){
 if(busy)return;if(files.Count==0){MessageBox.Show("Добавьте DXF / Add DXF files");return;}double v;string t=tol.Text.Replace(',','.');if(!Double.TryParse(t,NumberStyles.Float,CultureInfo.InvariantCulture,out v)||Double.IsNaN(v)||Double.IsInfinity(v)||v<0.0000001||v>1){MessageBox.Show("Макс. отклонение / Max. deviation: 0.0000001–1 mm");return;}string[] cut=layers.Text.Split(',').Select(x=>x.Trim()).Where(x=>x.Length>0).ToArray();if(cut.Length==0){MessageBox.Show("Укажите слои / Specify CUT layers");return;}
 busy=true;EnsureSelection();foreach(var b in buttons)b.Enabled=false;output.Enabled=tol.Enabled=layers.Enabled=browse.Enabled=false;progress.Style=ProgressBarStyle.Marquee;status.Text="Обработка / Processing…";UpdateDashboard(null);string request=null;
 try{string temp=Path.Combine(Path.GetTempPath(),"CNCFileDoctor");Directory.CreateDirectory(temp);request=Path.Combine(temp,Guid.NewGuid().ToString("N")+".json");var data=new Dictionary<string,object>{{"inputs",files.ToArray()},{"outputMode","source-folder"},{"convert",convert},{"splitCriteria",splitCriteria},{"tolerance",t},{"layers",cut},{"language",lang.SelectedIndex==0?"ru":"en"}};File.WriteAllText(request,json.Serialize(data),new UTF8Encoding(false));string req=request;var result=await Task.Run(()=>Python("--request "+Quote(req)));if(Launcher.SelfTest)File.WriteAllText(Path.Combine(root,"build","gui-protocol.txt"),result.Item1+"\n"+result.Item2+"\n"+result.Item3);string r=req+".result.json";if(!File.Exists(r))throw new Exception(result.Item3+result.Item2);var job=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(r));foreach(var obj in (System.Collections.IList)job["files"]){var f=(Dictionary<string,object>)obj;int idx=files.FindIndex(x=>String.Equals(x,(string)f["source"],StringComparison.OrdinalIgnoreCase));if(idx<0)continue;table.Items[idx].SubItems[1].Text=Friendly((string)f["status"]);table.Items[idx].SubItems[2].Text=String.Join(" ",((System.Collections.IList)f[lang.SelectedIndex==0?"findingsRu":"findingsEn"]).Cast<object>().Select(x=>x.ToString()));table.Items[idx].Tag=json.Serialize(f);}var first=(Dictionary<string,object>)((System.Collections.IList)job["files"])[0];report=(string)first["reportPath"];status.Text="Готово / Done: "+String.Join("; ",((System.Collections.IList)job["outputFolders"]).Cast<object>().Select(x=>x.ToString()));UpdateLocation();EnsureSelection();previewMode.SelectedIndex=1;await ShowPreview();if(result.Item1==1)MessageBox.Show("Есть ошибки / Some files failed; see report");}
 catch(Exception e){if(Launcher.SelfTest)throw;status.Text="Ошибка / Error";MessageBox.Show(e.Message,"CNC File Doctor");}
 finally{if(request!=null){if(File.Exists(request))File.Delete(request);if(File.Exists(request+".result.json"))File.Delete(request+".result.json");}busy=false;foreach(var b in buttons)b.Enabled=true;output.Enabled=tol.Enabled=layers.Enabled=browse.Enabled=true;progress.Style=ProgressBarStyle.Blocks;progress.Value=100;UpdateLocation();UpdateDashboard(CurrentFile());}}
 string Friendly(string code){bool ru=lang.SelectedIndex==0;switch(code){case "LAYER_SPLIT_PARTIAL":return ru?"Разделено; часть сохранена":"Split; some preserved";case "LAYER_SPLIT_COMPLETE":return ru?"Разделено по слоям":"Split into layers";case "CHECKED_CANDIDATE_REVIEW_REQUIRED":return ru?"Проверки пройдены":"Checks passed";case "BLOCKED_REVIEW":return ru?"Карантин":"Quarantine";case "BLOCKED":return ru?"Преобразование отклонено":"Conversion blocked";case "ERROR":return ru?"Ошибка":"Error";case "ISSUES_FOUND":return ru?"Есть замечания":"Issues found";default:return ru?"Проверка завершена":"Inspected";}}
 string Describe(Dictionary<string,object> f){bool ru=lang.SelectedIndex==0;var b=new StringBuilder();var d=f.ContainsKey("diagnosis")?(Dictionary<string,object>)f["diagnosis"]:f;b.AppendLine(Path.GetFileName(d["source"].ToString()));b.AppendLine((ru?"Единицы DXF: ":"DXF units: ")+((string)d["unitsCode"]=="4"?"mm":"unknown / other"));b.AppendLine();b.AppendLine(ru?"Объекты:":"Entities:");foreach(var kv in (Dictionary<string,object>)d["entityCounts"])b.AppendLine("  "+kv.Key+": "+kv.Value);b.AppendLine();if(f.ContainsKey("findingsRu")){foreach(var issue in (System.Collections.IList)f[ru?"findingsRu":"findingsEn"])b.AppendLine("• "+issue);}else{foreach(var issue in (System.Collections.IList)d[ru&&d.ContainsKey("issuesRu")?"issuesRu":"issues"])b.AppendLine("• "+issue);}if(f.ContainsKey("status"))b.AppendLine(Friendly((string)f["status"]));if(f.ContainsKey("sourceUnchanged"))b.AppendLine((bool)f["sourceUnchanged"]?(ru?"Исходный файл сохранён без изменений.":"Original file preserved unchanged."):(ru?"Исходный файл изменился во время обработки.":"Source changed during processing."));if(f.ContainsKey("candidate"))b.AppendLine((ru?"Результат: ":"Candidate: ")+f["candidate"]);if(f.ContainsKey("conversion")){var c=(Dictionary<string,object>)f["conversion"];if(c.ContainsKey("maximumWholeCurveBoundMm"))b.AppendLine((ru?"Оценка погрешности, мм: ":"Deviation bound, mm: ")+c["maximumWholeCurveBoundMm"]);}b.AppendLine();b.AppendLine(ru?"* Перед производством необходима проверка технологом. Подробности — в отчёте.":"* Manufacturing review required. See report for full details.");return b.ToString();}
 double N(Dictionary<string,object> n,string k){return n.ContainsKey(k)?Convert.ToDouble(n[k],CultureInfo.InvariantCulture):0;}
 async Task ShowPreview(){
  if(table.SelectedIndices.Count==0)return;
  int ticket=++serial,idx=table.SelectedIndices[0];string source=files[idx],path=source;
  Dictionary<string,object> fileInfo=table.Items[idx].Tag==null?null:json.Deserialize<Dictionary<string,object>>((string)table.Items[idx].Tag);
  bool candidateExists=fileInfo!=null&&fileInfo.ContainsKey("candidate")&&File.Exists((string)fileInfo["candidate"]);previewMode.Enabled=candidateExists;if(!candidateExists&&previewMode.SelectedIndex!=0){previewMode.SelectedIndex=0;return;}if(previewMode.SelectedIndex==1&&candidateExists)path=(string)fileInfo["candidate"];
  bool ru=lang.SelectedIndex==0;
  preview.Message=ru?"Загрузка контура…":"Loading contour…";preview.Invalidate();
  try{
   string scanArgs="--scan "+Quote(path);foreach(string layer in layers.Text.Split((char)44).Select(x=>x.Trim()).Where(x=>x.Length>0))scanArgs+=" --cut-layer "+Quote(layer);var r=await Task.Run(()=>Python(scanArgs));
   if(ticket!=serial||IsDisposed||idx>=table.Items.Count||files[idx]!=source)return;
   if(r.Item1!=0)throw new Exception(r.Item3);
   var d=json.Deserialize<Dictionary<string,object>>(r.Item2);var curves=new List<WorldPoint[]>();var colors=new List<Color>();var pending=new HashSet<int>();var changed=new HashSet<int>();var changedHandles=new HashSet<string>();if(path!=source&&fileInfo!=null&&fileInfo.ContainsKey("conversion")){var conversion=(Dictionary<string,object>)fileInfo["conversion"];foreach(var item in (System.Collections.IList)conversion["splines"]){var spline=(Dictionary<string,object>)item;if(spline.ContainsKey("pieces"))foreach(var raw in (System.Collections.IList)spline["pieces"]){var piece=(Dictionary<string,object>)raw;if(piece.ContainsKey("outputHandle"))changedHandles.Add((string)piece["outputHandle"]);}}if(conversion.ContainsKey("normalization")){var proof=(Dictionary<string,object>)conversion["normalization"];foreach(var raw in (System.Collections.IList)proof["records"]){var row=(Dictionary<string,object>)raw;foreach(var h in (System.Collections.IList)row["outputHandles"])changedHandles.Add(h.ToString());}}}
   foreach(var obj in (System.Collections.IList)d["geometry"]){
    var g=(Dictionary<string,object>)obj;int curveIndex=curves.Count;int rgb=g.ContainsKey("displayRgb")?Convert.ToInt32(g["displayRgb"]):0x6ed9f7;colors.Add(Color.FromArgb((rgb>>16)&255,(rgb>>8)&255,rgb&255));if(path==source&&g.ContainsKey("pending")&&(bool)g["pending"])pending.Add(curveIndex);if(g.ContainsKey("handle")&&changedHandles.Contains((string)g["handle"]))changed.Add(curveIndex);if(g.ContainsKey("points")){curves.Add(((System.Collections.IList)g["points"]).Cast<object>().Select(p=>{var xy=(System.Collections.IList)p;return new WorldPoint(Convert.ToDouble(xy[0]),Convert.ToDouble(xy[1]));}).ToArray());continue;}var n=(Dictionary<string,object>)g["n"];string typ=(string)g["type"];
    if(typ=="LINE")curves.Add(new[]{new WorldPoint(N(n,"10"),N(n,"20")),new WorldPoint(N(n,"11"),N(n,"21"))});
    else{double a=typ=="ARC"?N(n,"50"):0,sweep=typ=="ARC"?((N(n,"51")-a)%360+360)%360:360;var pts=new WorldPoint[65];for(int j=0;j<65;j++){double angle=(a+sweep*j/64)*Math.PI/180;pts[j]=new WorldPoint(N(n,"10")+N(n,"40")*Math.Cos(angle),N(n,"20")+N(n,"40")*Math.Sin(angle));}curves.Add(pts);}
   }
   var roleHandles=new Dictionary<string,Color>();System.Collections.IList classified=null;
   if(fileInfo!=null&&fileInfo.ContainsKey("conversion")){var cv=(Dictionary<string,object>)fileInfo["conversion"];if(cv.ContainsKey("topologyComparison")){var tp=(Dictionary<string,object>)cv["topologyComparison"];if(tp.ContainsKey("verifiedAtJoinTolerance")&&(bool)tp["verifiedAtJoinTolerance"]){string key=path==source?"sourceContours":"contours";if(tp.ContainsKey(key))classified=(System.Collections.IList)tp[key];}}}
   if(classified==null&&path==source&&fileInfo!=null&&fileInfo.ContainsKey("contourClassification")){var cl=(Dictionary<string,object>)fileInfo["contourClassification"];if((bool)cl["verified"])classified=(System.Collections.IList)cl["contours"];}
   if(classified!=null)foreach(var raw in classified){var ct=(Dictionary<string,object>)raw;string role=(string)ct["role"];Color roleColor=role=="OUTER"?Color.FromArgb(97,218,251):role=="HOLE"?Color.FromArgb(255,198,83):Color.FromArgb(199,146,255);foreach(var h in (System.Collections.IList)ct["handles"])roleHandles[h.ToString()]=roleColor;}
   preview.RoleColors.Clear();int roleIndex=0;foreach(var raw in (System.Collections.IList)d["geometry"]){var geo=(Dictionary<string,object>)raw;if(geo.ContainsKey("handle")&&roleHandles.ContainsKey((string)geo["handle"]))preview.RoleColors[roleIndex]=roleHandles[(string)geo["handle"]];roleIndex++;}
   preview.Curves=curves;preview.Colors=colors;preview.Pending=pending;preview.Changed=changed;preview.Problems.Clear();preview.Units=d.ContainsKey("unitsCode")&&(string)d["unitsCode"]=="4"?"mm":"DXF";bool partial=false;if(d.ContainsKey("diagnostics")){var diagnostics=(Dictionary<string,object>)d["diagnostics"];partial=(bool)diagnostics["partial"];foreach(var raw in (System.Collections.IList)diagnostics["markers"]){var marker=(Dictionary<string,object>)raw;if((string)marker["code"]=="UNSUPPORTED")continue;var point=(System.Collections.IList)marker["point"];preview.Problems.Add(new PreviewMarker(){Point=new WorldPoint(Convert.ToDouble(point[0]),Convert.ToDouble(point[1])),Message=(string)marker[ru?"messageRu":"messageEn"]});}}if(fileInfo!=null&&fileInfo.ContainsKey("conversion")){var conversion=(Dictionary<string,object>)fileInfo["conversion"];if(conversion.ContainsKey("intersectionCheck")){var check=(Dictionary<string,object>)conversion["intersectionCheck"];if(check.ContainsKey("unresolved")){var involved=new HashSet<string>();foreach(var raw in (System.Collections.IList)check["unresolved"]){var pair=(Dictionary<string,object>)raw;foreach(string key in new[]{"first","second"})if(pair.ContainsKey(key))involved.Add(pair[key].ToString());}int position=0;foreach(var raw in (System.Collections.IList)d["geometry"]){var g=(Dictionary<string,object>)raw;if(g.ContainsKey("handle")&&involved.Contains((string)g["handle"])&&position<curves.Count&&curves[position].Length>0)preview.Problems.Add(new PreviewMarker(){Point=curves[position][curves[position].Length/2],Message=ru?"Возможное пересечение/наложение у этого объекта. Требуется проверка.":"Possible intersection/overlap near this entity. Review required."});position++;}}}}
preview.Fit();displayedPath=source;
   preview.Message=ru?"В этом файле нет объектов, поддерживаемых просмотром. После преобразования будет показан результат, если он создан.":"No preview-supported entities in this file. A generated candidate will be displayed after conversion.";
   hint.Text=(path==source?(ru?"Исходный DXF: ":"Source DXF: "):(ru?"Результат обработки: ":"Processed candidate: "))+Path.GetFileName(path)+"  | "+(ru?"Маркеров: ":"Markers: ")+preview.Problems.Count+(partial?(ru?" · неполный просмотр":" · partial preview"):"");
   preview.Invalidate();d.Remove("geometry");details.Text=ReadableDetails(Describe(fileInfo??d));UpdateDashboard(fileInfo??d);
  }catch(Exception e){
   if(ticket==serial){displayedPath=null;preview.Curves.Clear();preview.Message=ru?"Не удалось показать контур. Причина указана справа.":"Unable to display contour. See details on the right.";preview.Invalidate();details.Text=e.Message;}
  }
 }
